function rebuildMasks(){if(!state)return;maskE=createCanvas();const customP=createCanvas();for(const cmd of state.draft.commands){if(cmd.kind==='clear'){applyCommand(maskE,cmd);applyCommand(customP,cmd)}else applyCommand(cmd.target==='protect'?customP:maskE,cmd)}if(currentStroke&&currentStroke.kind!=='pan'){applyCommand(currentStroke.target==='protect'?customP:maskE,currentStroke)}maskP=createCanvas();drawPresetProtection(maskP);maskP.getContext('2d').drawImage(customP,0,0);maskA=createCanvas();const e=maskE.getContext('2d').getImageData(0,0,state.width,state.height),p=maskP.getContext('2d').getImageData(0,0,state.width,state.height),a=maskA.getContext('2d').createImageData(state.width,state.height);let raw=0,allowed=0,overlap=0,x0=state.width,y0=state.height,x1=-1,y1=-1;for(let i=0;i<e.data.length;i+=4){if(e.data[i+3]<128)continue;raw++;if(p.data[i+3]>=128){overlap++;continue}const n=i/4,x=n%state.width,y=Math.floor(n/state.width);if(state.isSample&&(x<60||x>708||y<28||y>484))continue;allowed++;a.data[i]=a.data[i+1]=a.data[i+2]=a.data[i+3]=255;x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y)}maskA.getContext('2d').putImageData(a,0,0);const bbox=allowed?[x0,y0,x1+1,y1+1]:null;const context=bbox?[Math.max(0,x0-28),Math.max(0,y0-60),Math.min(state.width,x1+29),Math.min(state.height,y1+29)]:null;maskStats={raw,allowed,overlap,bbox,context};$('maskCount').textContent=fmt(allowed);$('protectedCount').textContent=fmt(overlap);$('stageHelper').classList.toggle('hidden',raw>0);updateDraftButtons();draw()}
function tintMask(ctx,mask,color,alpha){if(!mask)return;const c=createCanvas();const t=c.getContext('2d');t.drawImage(mask,0,0);t.globalCompositeOperation='source-in';t.fillStyle=color;t.fillRect(0,0,c.width,c.height);ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(c,0,0);ctx.restore()}
