function drawNow(){const canvas=$('editorCanvas');if(!canvas||!state||!currentImage||!canvas.width)return;const ctx=canvas.getContext('2d'),dpr=Math.max(1,window.devicePixelRatio||1);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,stageSize.w,stageSize.h);ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);ctx.shadowColor='#18364615';ctx.shadowBlur=22/view.scale;ctx.shadowOffsetY=4/view.scale;ctx.fillStyle='white';ctx.fillRect(0,0,state.width,state.height);ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.drawImage(currentImage,0,0,state.width,state.height);if($('showProtect').checked&&maskStats.raw){tintMask(ctx,maskP,'#c69a57',.10)}if($('showEdit').checked)tintMask(ctx,maskA,'#18a681',.30);if($('showProtect').checked&&maskStats.overlap){const c=createCanvas();const cc=c.getContext('2d');cc.drawImage(maskE,0,0);cc.globalCompositeOperation='destination-in';cc.drawImage(maskP,0,0);tintMask(ctx,c,'#d99939',.32)}if($('showContext').checked&&maskStats.context){const [x,y,x2,y2]=maskStats.context;ctx.strokeStyle='#6b98bc';ctx.lineWidth=1.4/view.scale;ctx.setLineDash([5/view.scale,4/view.scale]);ctx.strokeRect(x,y,x2-x,y2-y);ctx.setLineDash([])}if(pointerPos&&inside(pointerPos)&&['brush','erase','protect'].includes(tool)&&!spaceHeld&&!jobBusy){ctx.strokeStyle=tool==='protect'?'#b37b30':'#298b75';ctx.lineWidth=1/view.scale;ctx.beginPath();ctx.arc(pointerPos[0],pointerPos[1],Number($('brushSize').value)/2,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function commitStroke(cmd){state.draft.commands.push(cmd);state.draft.redo=[];rebuildMasks();scheduleSave()}
function pointerDown(ev){if(jobBusy||!state||ev.button!==0)return;const p=sourcePoint(ev);$('editorCanvas').focus({preventScroll:true});$('editorCanvas').setPointerCapture(ev.pointerId);if(tool==='pan'||spaceHeld){currentStroke={kind:'pan'};dragOrigin={x:ev.clientX,y:ev.clientY,vx:view.x,vy:view.y};$('editorCanvas').style.cursor='grabbing';return}if(!inside(p)){currentStroke=null;return}const target=tool==='protect'?'protect':tool==='erase'&&$('eraseTarget').value==='protect'?'protect':'edit';currentStroke={kind:tool==='rect'?'rect':'stroke',target,erase:tool==='erase',width:Number($('brushSize').value),points:[p],created_at:now()};if(tool==='rect')currentStroke.points.push(p);rebuildMasks();ev.preventDefault()}
